input.command:
set -e
cat > /etc/nginx/sites-available/git-deploy <<'EOF'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;

    root /var/www/html;
    index index.html index.htm;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
ln -sf /etc/nginx/sites-available/git-deploy /etc/nginx/sites-enabled/git-deploy
rm -f /etc/nginx/sites-enabled/default
nginx -t
# start nginx (no systemd in this container)
nginx
sleep 1
curl -sS -o /dev/null -w 'nginx HTTP %{http_code}\n' http://127.0.0.1:8080/ || true
